def test_request_state_object() -> None:
    lifespan_state = State({"old": "foo", "items": []})
    scope: Scope = {"type": "http", "state": lifespan_state}

    s = Request(scope).state

    assert s["old"] == "foo"
    assert list(s) == ["old", "items"]
    assert len(s) == 2

    s["new"] = "value"
    assert s.new == "value"
    assert lifespan_state["new"] == "value"

    del s["new"]

    s.new = "value"
    assert s["new"] == "value"

    s.items.append(1)
    assert lifespan_state.items == [1]

    del s.new

    with pytest.raises(AttributeError):
        s.new


